  'his-girl-friday': {"poster":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/21/His_Girl_Friday_%281940_poster%29_crop.jpg/500px-His_Girl_Friday_%281940_poster%29_crop.jpg","cast":["Cary Grant","Rosalind Russell","Ralph Bellamy","Gene Lockhart","Porter Hall","Ernest Truex","Cliff Edwards","John Qualen"],"directors":["Howard Hawks"],"synopsis":"La Dame du vendredi (His Girl Friday) est un film américain en noir et blanc réalisé par Howard Hawks, sorti en 1940.\nC'est l'adaptation de The Front Page, une  comédie en trois actes de Broadway de 1928 écrite par d'anciens reporters, Ben Hecht et Charles MacArthur.","wikiUrl":"https://fr.wikipedia.org/wiki/La_Dame_du_vendredi","qid":"Q1066714"},
  'la-kermesse-heroique': {"poster":"https://upload.wikimedia.org/wikipedia/en/8/81/LaKermesseH%C3%A9roique.jpg","cast":["Françoise Rosay","Jean Murat","Louis Jouvet","André Alerme","Will Dohm","Paul Hartmann","Albert Lieven","Paul Westermeier"],"directors":["Jacques Feyder"],"synopsis":"La Kermesse héroïque est un film franco-allemand de Jacques Feyder, d'après une nouvelle de Charles Spaak, sorti en 1935.","wikiUrl":"https://fr.wikipedia.org/wiki/La_Kermesse_h%C3%A9ro%C3%AFque","qid":"Q941279"},
  'le-roman-d-un-tricheur': {"poster":"https://upload.wikimedia.org/wikipedia/en/a/a3/Confessions-of-a-cheat-poster.jpg","cast":["Sacha Guitry","Jacqueline Delubac","Marguerite Moreno","Pauline Carton","Fréhel","Adolphe Borchard","Elmire Vautier","Fernand Trignol"],"directors":["Sacha Guitry"],"synopsis":"Le Roman d'un tricheur est un film français réalisé par Sacha Guitry, sorti en 1936, adaptation du roman de Guitry, Mémoires d'un tricheur.","wikiUrl":"https://fr.wikipedia.org/wiki/Le_Roman_d'un_tricheur","qid":"Q3226620"},
  'marius-1931': {"poster":"https://upload.wikimedia.org/wikipedia/en/f/fd/Marius_%28film%29.jpg","cast":["Raimu","Pierre Fresnay","Alexandre Mihalesco","Alida Rouffe","Édouard Delmont","Fernand Charpin","Lucien Callamand","Orane Demazis"],"directors":["Alexander Korda"],"synopsis":"« Marius » est un film français réalisé par Alexander Korda, sorti en octobre 1931.\nÉcrit par Marcel Pagnol d'après sa pièce éponyme, représentée pour la première fois le samedi 9 mars 1929 sur la scène du Théâtre de Paris, le film « Marius » est le premier volet de la « Trilogie marseillaise », selon l'appellation générique donnée à la suite de trois tragédies de Marcel Pagnol. Il précède « Fanny », sorti en 1932, et « César », sorti en 1936.","wikiUrl":"https://fr.wikipedia.org/wiki/Marius_(film%2C_1931)","qid":"Q2443227"},
  'angelitos-negros': {"cast":["Q467954","Emilia Guiú","Rita Montaner","María Douglas"],"directors":["Joselito Rodríguez"],"synopsis":"Angelitos negros (English: \"Little Black Angels\") is a 1948 Mexican drama film directed and co-written by Joselito Rodriguez and starring Pedro Infante, Emilia Guiú, Rita Montaner and Chela Castro.\nThe film deals with themes such as racism, self deprecation, negligence, poverty and social classes.","wikiUrl":"https://en.wikipedia.org/wiki/Angelitos_negros_(1948_film)","qid":"Q5676649"},
  'dos-tipos-de-cuidado': {"poster":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b6/Dos_tipos_de_cuidado_-_cartel_de_la_pel%C3%ADcula.jpg/500px-Dos_tipos_de_cuidado_-_cartel_de_la_pel%C3%ADcula.jpg","cast":["Q467954","Jorge Negrete","Carmelita González","Yolanda Varela","Carlos Orellana","José Elías Moreno","Q2865959","Mimí Derba"],"directors":["Ismael Rodríguez"],"synopsis":"Dos tipos de cuidado est un film mexicain réalisé par Ismael Rodríguez, sorti en 1953.","wikiUrl":"https://fr.wikipedia.org/wiki/Dos_tipos_de_cuidado","qid":"Q5299229"},
  'los-tres-garcia': {"poster":"https://upload.wikimedia.org/wikipedia/en/f/ff/The_Three_Garcias.jpeg","cast":["Q467954","Q3123282","Marga López","Abel Salazar"],"directors":["Ismael Rodríguez"],"synopsis":"Los tres García est un film mexicain réalisé par Ismael Rodríguez, sorti en 1947.","wikiUrl":"https://fr.wikipedia.org/wiki/Los_tres_Garc%C3%ADa","qid":"Q6683467"},
  'phantom-lady': {"poster":"https://upload.wikimedia.org/wikipedia/en/d/de/Phantomlady3.jpg","cast":["Franchot Tone","Ella Raines","Alan Curtis","Elisha Cook Jr.","Thomas Gomez","Regis Toomey","Aurora Miranda","Andrew Tombes"],"directors":["Robert Siodmak"],"synopsis":"Les Mains qui tuent ou La Femme fantôme, titre en Belgique (Phantom Lady) est un film américain, réalisé par Robert Siodmak, sorti le 28 janvier 1944 aux États-Unis et le 3 octobre 1946 en France.\nFilm noir, il est l'adaptation du roman éponyme de William Irish et le premier film produit par Joan Harrison, première femme productrice engagée par Universal et également ancienne secrétaire et scénariste d'Alfred Hitchcock.","wikiUrl":"https://fr.wikipedia.org/wiki/Les_Mains_qui_tuent","qid":"Q1953971"},
  'criss-cross': {"poster":"https://upload.wikimedia.org/wikipedia/en/1/1a/Criss_Cross_%28film%29_poster.jpg","cast":["Burt Lancaster","Yvonne De Carlo","Dan Duryea","Stephen McNally","Alan Napier","Richard Long","Griff Barnett","John Doucette"],"directors":["Robert Siodmak"],"synopsis":"Pour toi j'ai tué (Criss Cross) est un film noir américain réalisé par Robert Siodmak, sorti en 1949. Cette production à petit budget bénéficie d'une solide mise en scène et du duo formé par Burt Lancaster et Yvonne De Carlo.","wikiUrl":"https://fr.wikipedia.org/wiki/Pour_toi_j'ai_tu%C3%A9","qid":"Q2077169"},
