  'pokolenie': {"poster":"https://upload.wikimedia.org/wikipedia/en/7/71/A_generation.jpg","cast":["Roman Polanski","Tadeusz Łomnicki","Urszula Modrzyńska","Tadeusz Janczar","Q168049","Janusz Paluszkiewicz","Ryszard Kotys","Zofia Czerwińska"],"directors":["Andrzej Wajda"],"synopsis":"Une fille a parlé (Pokolenie) est un film polonais réalisé par Andrzej Wajda, sorti en 1955.","wikiUrl":"https://fr.wikipedia.org/wiki/Une_fille_a_parl%C3%A9","qid":"Q1306396"},
  'struktura-krysztalu': {"cast":["Barbara Wrzesińska","Daniel Olbrychski","Andrzej Żarnecki","Monika Dzienisiewicz"],"directors":["Krzysztof Zanussi"],"synopsis":"The Structure of Crystal (Polish: Struktura kryształu) is a 1969 Polish film directed by Krzysztof Zanussi. It is his debut feature, and it won the Mermaid Award at the Warsaw Film Festival.","wikiUrl":"https://en.wikipedia.org/wiki/The_Structure_of_Crystal","qid":"Q4444352"},
  'krajobraz-po-bitwie': {"poster":"https://upload.wikimedia.org/wikipedia/en/c/c8/Poster_for_Krajobraz_po_bitwie_by_Andrzej_Wajda.jpg","cast":["Daniel Olbrychski","Aleksander Bardini","Stanislava Celińska","Tadeusz Janczar","Zygmunt Malanowicz","Anna German","Małgorzata Braunek","Jerzy Zelnik"],"directors":["Andrzej Wajda"],"synopsis":"Paysage après la bataille (Krajobraz po bitwie) est un film polonais réalisé par Andrzej Wajda, sorti en 1970.","wikiUrl":"https://fr.wikipedia.org/wiki/Paysage_apr%C3%A8s_la_bataille","qid":"Q1372578"},
  'shatranj-ke-khilari': {"poster":"https://upload.wikimedia.org/wikipedia/en/0/0b/The_Chess_Players_%281977_film%29.jpg","cast":["Shabana Azmi","Farida Jalal","Richard Attenborough","Sanjeev Kumar","Saeed Jaffrey","Victor Banerjee","Amjad Khan","Tom Alter"],"directors":["Satyajit Ray"],"synopsis":"Les Joueurs d'échecs (शतरंज के खिलाड़ी, Shatranj Ke Khilari) est un film indien du réalisateur bengali Satyajit Ray, sorti en 1977. Il est inspiré de la nouvelle éponyme de Munshi Premchand. Richard Attenborough y interprète le rôle du général James Outram, et Amjad Khan celui du roi d'Oudh, Wajid Ali Shah.","wikiUrl":"https://fr.wikipedia.org/wiki/Les_Joueurs_d'%C3%A9checs_(film)","qid":"Q76582"},
  'aakrosh': {"poster":"https://upload.wikimedia.org/wikipedia/en/0/00/Aakrosh80.jpg","cast":["Naseeruddin Shah","Om Puri","Smita Patil","Amrish Puri","Reema Lagoo","Nana Palsikar","Achyut Potdar","Deepak Shirke"],"directors":["Govind Nihalani"],"synopsis":"Aakrosh  est un film indien de Bollywood réalisé par Govind Nihalani, sorti en 1980, qui s'inspire d'un incident juridique réel et a pour thème les conditions de vie des adivasis dans le Maharashtra. Les acteurs principaux sont Naseeruddin Shah et Om Puri, qui joue un rôle quasiment muet.","wikiUrl":"https://fr.wikipedia.org/wiki/Aakrosh","qid":"Q2680157"},
